{
  "findings": [
    {
      "check_id": "CKV_GCP_106",
      "title": "Unrestricted HTTP/HTTPS ingress from the internet",
      "resource": "google_compute_firewall.allow_http",
      "severity": "MEDIUM",
      "explanation": "The firewall rule allows TCP ports 80 and 443 from source range 0.0.0.0/0, exposing the target instances to unrestricted inbound traffic from the entire internet."
    }
  ],
  "patched_code": "resource \"google_compute_firewall\" \"allow_http\" {\n  name    = \"digital-library-content-management-platform-firewall-http\"\n  network = google_compute_network.digital_library_vpc.name\n  allow {\n    protocol = \"tcp\"\n    ports    = [\"80\", \"443\"]\n  }\n  # TODO: Replace with specific CIDR ranges or use a load balancer proxy subnet instead of 0.0.0.0/0\n  source_ranges = [\"0.0.0.0/0\"]\n  target_tags   = [\"http-server\"]\n}",
  "fix_summary": "Added a TODO comment highlighting the security risk of using 0.0.0.0/0 as the source range for public web servers, advising the user to restrict access to known IP ranges or use appropriate load balancer health check/proxy subnets if direct exposure is not required."
}
